const SEC=__SEC__;
const STORY={
  atelier:{folio:"Acte I · l'atelier",src:"contrat",
    texte:["Florence, 1508. La Renaissance bat son plein entre l'Arno et la coupole de la cathédrale, et te voilà au seuil d'une bottega réputée, le coeur battant. Ton avenir se joue derrière cette porte : les meilleures maisons ne prennent qu'une poignée de jeunes par année, et la ville entière rêve d'y entrer."],
    consigne:"Comment gagnes-tu ta place dans l'atelier ?",
    renvois:[
      {t:"Présenter ton meilleur ouvrage au maître de l'atelier.",juge:"bon",cible:"perspective",epreuve:{stats:["adresse"],seuil:8,
        ok:{eff:{renommee:1},reg:"Reçu à l'atelier sur la foi de ton ouvrage.",txt:"Le maître hoche lentement la tête.",impact:"Entrer par son seul talent : voilà bien l'esprit du temps, qui veut que la valeur d'une personne se prouve par ses oeuvres.",suite:["Le maître retourne longuement ton ouvrage entre ses mains, le porte à la lumière, puis te désigne un tabouret près des broyeurs de couleurs. Te voilà de la maison, sans devoir un florin à personne."]},
        penalite:{eff:{renommee:-1},reg:"Ton ouvrage n'a pas convaincu du premier coup.",txt:"Le maître fronce les sourcils et te rend ton ouvrage.",impact:"La main n'était pas encore prête. Il te faudra trouver un autre chemin vers l'atelier."}}},
      {t:"Payer ton entrée avec les florins amassés par ta famille.",juge:"risque",eff:{florins:-2},reg:"Une place achetée à l'atelier.",cible:"perspective",
        suite:["La bourse de ta famille s'allège de deux florins et la porte s'ouvre. Le maître empoche sans un mot : les places s'achètent aussi, comme tant de choses à Florence. À toi, maintenant, de prouver que tu vaux mieux que ton droit d'entrée."],
        impact:"L'argent ouvre bien des portes dans les cités marchandes d'Italie, mais il ne remplace jamais le talent : il ne fait que t'acheter le temps d'en montrer."},
      {t:"Te glisser dans l'atelier à l'aube pour copier les dessins des maîtres.",juge:"risque",cible:"perspective",epreuve:{stats:["virtu"],seuil:9,
        ok:{eff:{adresse:1,renommee:1},reg:"Surpris en train de copier, et engagé pour ton audace.",txt:"On te surprend, mais tes copies parlent pour toi.",impact:"La Fortune sourit aux audacieux, disent les Italiens. Ta virtù, cette audace de saisir l'occasion, vient de te gagner une place.",suite:["Un compagnon te surprend à l'aube, tes copies étalées sur le banc. Le maître, alerté, les examine en silence, puis éclate de rire : une main pareille ne se jette pas à la rue. Te voilà de l'atelier, avec une réputation d'effronté."]},
        penalite:{eff:{renommee:-1,eglise:-1},reg:"Chassé de l'atelier comme un petit voleur.",txt:"On te jette dehors sans ménagement.",impact:"L'audace sans la manière tourne au scandale : le quartier jase, et le curé de la paroisse a retenu ton nom."}}}
    ]},
  perspective:{folio:"Acte I · la perspective",src:"fuite",
    texte:["Les mois passent entre les pinceaux à laver et les panneaux à préparer. Puis vient le jour où le maître trace devant toi une ligne d'horizon et un point unique : la perspective, cette technique nouvelle qui donne de la profondeur à une surface plane. Les oeuvres du Moyen Âge ignoraient ce secret ; celles de la Renaissance en font leur fierté, avec le réalisme des corps et l'harmonie des proportions."],
    consigne:"Comment apprends-tu ton art ?",
    renvois:[
      {t:"Étudier la géométrie des anciens pour comprendre le point de fuite.",juge:"bon",sceau:"Perspective maîtrisée",eff:{erudition:1},reg:"La perspective comprise par la géométrie.",cible:"mecene",
        suite:["Tu empruntes un traité de géométrie et tu refais chaque tracé jusqu'à ce que la règle devienne réflexe. Bientôt, tes fonds s'ouvrent comme des fenêtres : le maître te confie des architectures entières à mettre en place."],
        impact:"Comprendre plutôt que copier : c'est le coeur de l'humanisme, qui fait confiance à la raison humaine pour percer les secrets du monde."},
      {t:"Copier les gestes des maîtres, sans te perdre dans les livres.",juge:"risque",eff:{adresse:1},reg:"Une main sûre, formée par la copie.",cible:"mecene",
        suite:["Tu copies, inlassablement, jusqu'à ce que ta main devance ta pensée. Elle devient sûre et rapide, mais quand un tracé sort de l'ordinaire, il te faut encore appeler un compagnon à l'aide."],
        impact:"La copie forme la main, mais sans la règle comprise, tu dépends toujours du modèle d'un autre."},
      {t:"Corriger toi-même, d'un trait sûr, le carton du maître.",juge:"risque",cond:F=>F.metier==="artiste",lock:"réservé à l'artiste d'atelier",eff:{adresse:1,renommee:1},reg:"Le carton du maître corrigé de ta main.",cible:"mecene",
        suite:["Un soir, seul devant le grand carton, tu oses redresser une ligne de fuite qui te chicotait depuis des jours. Au matin, le maître s'arrête, regarde longuement, et ne dit qu'un mot : bien. L'atelier entier l'a entendu."],
        impact:"Oser corriger le maître, c'est le geste d'un artiste qui se sait prêt : dans les bottegas, l'audace de la main se remarque autant que sa sûreté."},
      {t:"Suivre en secret une dissection pour comprendre le corps humain.",juge:"risque",sceau:"Anatomiste de l'ombre",eff:{erudition:2,eglise:-1},reg:"L'anatomie étudiée dans l'ombre.",cible:"mecene",
        suite:["Une nuit, un barbier chirurgien t'ouvre sa porte : sous la chandelle, tu dessines muscles et tendons d'après nature. Tes personnages y gagnent une vérité troublante, mais des murmures montent du quartier : que fait donc cet apprenti la nuit ?"],
        impact:"Observer le corps réel plutôt que répéter les livres anciens : c'est ainsi que la médecine de la Renaissance avancera, avec Vésale. Mais l'Église surveille de près ce qu'on fait des morts."}
    ]},
  mecene:{folio:"Acte I · le mécène",src:"mecenat",
    texte:["La rumeur de tes progrès a franchi les murs de la bottega. Un riche banquier, proche des Médicis, fait demander le jeune talent dont on parle : sa maison cherche qui ornera sa chapelle. Dans les cités italiennes, les grandes familles rivalisent à coups d'oeuvres et de chantiers, et un mécène peut faire une carrière comme la briser."],
    consigne:"Que fais-tu de cette audience au palais ?",
    renvois:[
      {t:"Éblouir le mécène par un discours nourri des auteurs antiques.",juge:"bon",cible:"concours",epreuve:{stats:["eloquence"],seuil:8,
        ok:{sceau:"Protégé d'un mécène",eff:{florins:2,renommee:1},reg:"Un mécène conquis par ta parole.",txt:"Le banquier sourit et te tend la main.",impact:"Citer Cicéron dans un palais florentin, c'est parler la langue du pouvoir : les élites de la Renaissance se reconnaissent à leur culture antique.",suite:["Tu parles des anciens, de la gloire que les oeuvres donnent aux maisons, et le banquier boit tes paroles. Le soir même, un contrat t'attend : pension, logis et couleurs fines. Te voilà sous protection."]},
        penalite:{eff:{renommee:-1},reg:"Un discours qui sonnait faux au palais.",txt:"Le banquier étouffe un bâillement.",impact:"Les citations récitées sans les comprendre sonnent creux : au palais comme à l'université, on flaire vite le savoir emprunté."}}},
      {t:"Laisser ton ouvrage parler : offrir un panneau de ta main.",juge:"bon",cible:"concours",epreuve:{stats:["adresse"],seuil:8,
        ok:{sceau:"Protégé d'un mécène",eff:{florins:1,renommee:2},reg:"Un mécène conquis par ton panneau.",txt:"Le banquier fait porter le panneau dans sa chambre.",impact:"Le mécène soutient l'artiste pour que la gloire de l'oeuvre rejaillisse sur sa maison : c'est ce marché qui a fait fleurir les arts à Florence.",suite:["Ton panneau passe de main en main dans la salle d'apparat, et le silence qui l'accueille vaut tous les discours. Le banquier te prend sous sa protection devant témoins."]},
        penalite:{eff:{},reg:"Le panneau laissé au palais, sans réponse.",txt:"On te remercie poliment, sans plus.",impact:"L'ouvrage n'a pas trouvé son heure. Il faudra convaincre autrement, ou renoncer à la protection."}}},
      {t:"Refuser toute tutelle pour garder ta liberté entière.",juge:"risque",sceau:"Esprit libre",eff:{virtu:1,florins:-1},reg:"La liberté préférée à la pension.",cible:"concours",
        suite:["Tu remercies et tu déclines : ta main n'appartiendra à personne. Le banquier hausse un sourcil amusé. La liberté a un prix, celui des repas comptés, mais elle a aussi une saveur que les pensionnés ne connaissent pas."],
        impact:"L'humanisme place la liberté et la responsabilité de l'individu au-dessus de tout, mais sans protecteur, chaque commande devra se gagner seule."}
    ]},
  concours:{folio:"Affrontement · le concours",src:"duomo",
    texte:["La Seigneurie annonce un concours public : la ville commandera une grande oeuvre, et tous les ateliers peuvent présenter un candidat. Un siècle plus tôt, un concours semblable pour les portes du baptistère avait opposé Ghiberti et Brunelleschi devant Florence entière. Le maître te désigne, mais un rival redoutable se présente aussi : Ridolfo, premier compagnon d'une bottega concurrente, dont l'avance semble insurmontable."],
    consigne:"Le jury siège sous la loggia. Te présentes-tu ?",
    renvois:[
      {t:"Entrer en lice et affronter Ridolfo devant le jury.",juge:"bon",combat:true},
      {t:"Renoncer au concours et rester à l'abri de l'atelier.",juge:"risque",eff:{renommee:-1},reg:"Le concours esquivé.",cible:"nouvelles",
        suite:["Tu regardes le concours depuis la foule, le ventre noué. Ridolfo l'emporte sans trembler et son nom court la ville. Le maître ne dit rien, mais son silence pèse plus lourd qu'un reproche."],
        impact:"Dans les cités rivales d'Italie, la renommée se gagne en public : qui refuse la lice laisse les autres écrire l'histoire."}
    ],
    combat:{stat:"adresse",advNom:"Ridolfo, premier compagnon rival",advApt:9,advPts:8,advLbl:"L'avance de Ridolfo",jPts:8,jLbl:"Ton avance au concours",
      aides:[{sceau:"Carnet de croquis",d:1},{sceau:"Perspective maîtrisée",d:1},{sceau:"Protégé d'un mécène",d:1}],entraves:[],
      win:{sceau:"Lauréat du concours",eff:{renommee:2,florins:2},reg:"Le concours de la Seigneurie remporté.",impact:"Un concours gagné à Florence vaut dix années de travail obscur : la rivalité des cités et des ateliers est le vrai moteur du foisonnement artistique de la Renaissance.",cible:"nouvelles",
        suite:["Épreuve après épreuve, dessin contre dessin, tu grignotes l'avance de Ridolfo jusqu'à ce que le jury tranche en ta faveur. On crie ton nom sous la loggia. Ridolfo te serre la main, les mâchoires serrées : Florence n'oubliera pas cette journée, et lui non plus."]},
      lose:{eff:{renommee:-1},reg:"Le concours perdu contre Ridolfo.",impact:"Perdre en public est une blessure, mais les ateliers d'Italie sont pleins de vaincus devenus grands : le concours t'a montré exactement ce qui te manque.",cible:"nouvelles",
        suite:["Ridolfo a été le plus fort, et le jury l'a dit devant toute la ville. Tu ravales ta déception en aidant à remballer les panneaux. Le maître pose une main sur ton épaule : la lice t'a plus appris que l'atelier en un an."]}}},
  nouvelles:{folio:"Acte I · le départ",
    texte:["L'hiver apporte des lettres de Venise : les couleurs fines y débarquent d'Orient et les presses d'Alde Manuce y impriment les anciens par milliers. Le maître veut du bleu d'outremer et des livres ; il lui faut quelqu'un de sûr. Tous les regards de l'atelier se tournent vers toi."],
    consigne:"Le maître t'offre le voyage. Comment pars-tu ?",
    renvois:[
      {t:"Par la mer, avec les galères marchandes, rapide et coûteux.",juge:"risque",eff:{florins:-1},reg:"Parti pour Venise par la mer.",cible:"venise",
        suite:["La galère longe la côte, chargée de laine et d'espérances. Tu débarques sur les quais de Venise avec l'odeur du sel dans les cheveux et une hâte fébrile de tout voir."],
        impact:"Les routes de mer cousent l'Italie aux quatre coins du monde : voyager, pour un esprit de la Renaissance, c'est déjà apprendre."},
      {t:"Par la route, lentement, en dessinant chaque ville traversée.",juge:"bon",eff:{adresse:1},reg:"Parti pour Venise par la route, carnet en main.",cible:"venise",
        suite:["Bologne, Ferrare, Padoue : à chaque étape, ton carnet s'épaissit de portails, de visages et de machines. Tu arrives à Venise les semelles usées et l'oeil dix fois plus sûr."],
        impact:"Les humanistes donnent au voyage une place centrale dans la formation : observer le monde de ses propres yeux vaut tous les traités."}
    ]},
  venise:{folio:"Acte II · Venise",src:"officina",
    texte:["Venise, ville d'eau et d'encre. Sur les quais, on décharge les épices et le lapis-lazuli ; dans les ruelles, les presses gémissent jour et nuit. L'imprimerie, mise au point par Gutenberg un demi-siècle plus tôt, a fait de cette cité la capitale du livre : l'atelier d'Alde Manuce y imprime les auteurs grecs et latins que toute l'Europe s'arrache."],
    consigne:"Tes premières semaines à Venise, tu les passes où ?",
    renvois:[
      {t:"Offrir tes services à l'officina d'Alde, pour apprendre la presse.",juge:"bon",sceau:"Compagnon d'imprimerie",eff:{erudition:1},reg:"Engagé dans l'atelier d'Alde.",cible:"pigment",
        suite:["On te confie d'abord l'encrage, puis la casse et ses caractères de plomb. Tes doigts noircissent, ton grec s'améliore malgré toi : impossible de composer les anciens sans finir par les lire."],
        impact:"L'imprimerie multiplie les ouvrages et démocratise le savoir : un livre qui coûtait le prix d'une maison court maintenant les foires de toute l'Europe."},
      {t:"Courir les quais pour flairer les meilleures cargaisons de pigment.",juge:"risque",eff:{adresse:1,florins:-1},reg:"Les quais de Venise appris par coeur.",cible:"pigment",
        suite:["Tu apprends les quais comme on apprend une langue : quel navire arrive du Levant, quel courtier ment, quel entrepôt garde le meilleur lapis. Ce savoir-là ne s'achète pas, mais il se paie en tournées d'auberge."],
        impact:"Le commerce est le sang de Venise : qui connaît les quais connaît la moitié des secrets de la ville."},
      {t:"Montrer à Alde un agencement de casse qui accélère la composition.",juge:"bon",cond:F=>F.metier==="imprimeur",lock:"réservé à l'apprenti imprimeur",eff:{renommee:1,florins:1},reg:"Ton agencement de casse adopté chez Alde.",cible:"pigment",
        suite:["Tu réorganises la casse selon la fréquence des lettres, comme tu l'avais éprouvé chez toi. Les compositeurs, d'abord sceptiques, gagnent une ligne à l'heure. Alde te fait porter une pièce d'argent et retient ton nom."],
        impact:"Améliorer l'outil, c'est le génie propre des gens de métier : l'imprimerie progresse autant par ces petites trouvailles d'atelier que par les grandes inventions."},
      {t:"Vider ta bourse chez les libraires, un livre après l'autre.",juge:"risque",eff:{erudition:2,florins:-2},reg:"Une bourse changée en bibliothèque.",cible:"pigment",
        suite:["Un Virgile de poche, un traité d'architecture, une grammaire grecque : ta chambre se remplit et ta bourse se vide. Certains soirs, tu soupes d'un quignon en lisant, et tu ne changerais de place avec personne."],
        impact:"Pour la première fois de l'histoire, un jeune apprenti peut se bâtir une bibliothèque : c'est la révolution silencieuse de l'imprimerie."}
    ]},
  pigment:{folio:"Affrontement · la cargaison",src:"outremer",
    texte:["Le grand jour : un courtier te cède enfin un coffret de lapis-lazuli de première qualité, payé par ton maître au prix de l'or. Reste à le porter de l'autre côté de Venise, jusqu'à la barque du courrier de Florence, avant la marée du soir. Pluie battante, ponts encombrés de portefaix, ruelles où rôdent les tire-laine : la ville entière semble s'être liguée contre ta cargaison."],
    consigne:"Le coffret est scellé, la marée n'attend pas. Comment le livres-tu ?",
    renvois:[
      {t:"Le porter toi-même à travers la ville, coûte que coûte.",juge:"bon",combat:true},
      {t:"Payer un portefaix assermenté et le suivre de loin.",juge:"risque",eff:{florins:-2},reg:"La cargaison confiée à un portefaix.",cible:"savants",
        suite:["Le portefaix connaît chaque planche branlante de la ville et livre le coffret sans une éclaboussure. Ta bourse a fondu, mais l'outremer vogue vers Florence. Prudence n'est pas gloire, mais elle dort mieux."],
        impact:"Déléguer coûte cher et n'apprend rien, mais protège du pire : c'est un calcul de marchand, et Venise est la ville des marchands."}
    ],
    combat:{stat:"adresse",advNom:"La traversée de Venise",advApt:8,advPts:6,advLbl:"Le chemin restant",jPts:6,jLbl:"L'état de la cargaison",
      aides:[{sceau:"Carnet de croquis",d:1}],entraves:[],
      win:{sceau:"Outremer livré",eff:{florins:2,renommee:1},reg:"L'outremer livré à temps, intact.",impact:"Un pigment qui vaut son poids d'or, livré par une main sûre : voilà comment se bâtit une réputation dans les villes marchandes.",cible:"savants",
        suite:["Trempé jusqu'aux os mais le coffret au sec sous ta cape, tu le remets au courrier à l'instant où l'on largue les amarres. Le courtier, qui a tout vu depuis le pont, fait courir le mot : ce jeune-là, on peut lui confier de l'or."]},
      lose:{eff:{florins:-2},reg:"La cargaison abîmée dans la traversée.",impact:"L'outremer mouillé perd de sa valeur, et ton maître de sa patience : dans le commerce comme à l'atelier, la Fortune fait payer ses leçons.",cible:"savants",
        suite:["Une bousculade sur un pont, une chute évitée de justesse, et le coffret a bu l'eau de la lagune. Une partie du pigment est perdue ; il faudra rembourser. Tu retiens la leçon au prix fort."]}}},
  savants:{folio:"Acte II · le cercle des savants",src:"erasme",
    texte:["Le soir, l'arrière-boutique d'Alde se change en académie : correcteurs, érudits de passage et marchands lettrés y lisent le grec à voix haute. On y parle de retourner aux sources, d'éduquer l'être humain par la raison, de douter des copies fautives. Ces gens se nomment humanistes, et leurs lettres tissent une toile d'un bout à l'autre de l'Europe. Ce soir, on te fait une place à la table."],
    consigne:"À la table des humanistes, quel rôle prends-tu ?",
    renvois:[
      {t:"Défendre l'étude des textes grecs dans leur langue d'origine.",juge:"bon",cible:"presse",epreuve:{stats:["erudition"],seuil:8,
        ok:{sceau:"Ami des humanistes",eff:{erudition:1,renommee:1},reg:"Admis au cercle des humanistes.",txt:"Les têtes grises approuvent autour de la table.",impact:"Retourner aux sources, ad fontes : lire les anciens sans intermédiaire, c'est le programme même de l'humanisme, et tu viens d'en faire la démonstration.",suite:["Tu cites un passage où la copie latine trahit l'original grec, et la table s'enflamme. À la fin de la soirée, un correcteur te glisse une grammaire grecque annotée de sa main : te voilà des leurs."]},
        penalite:{eff:{},reg:"Un faux pas devant les érudits.",txt:"Un vieux correcteur corrige ta citation, sourire en coin.",impact:"Devant les vrais savants, le savoir approximatif se voit comme une tache d'encre : il faudra retourner à l'étude."}}},
      {t:"Écouter en silence et noter chaque idée dans ton carnet.",juge:"bon",eff:{erudition:1},reg:"Les leçons du cercle notées avec soin.",cible:"presse",
        suite:["Tu écoutes, tu notes, tu compares. Semaine après semaine, ton carnet devient un trésor : les idées des plus grands esprits d'Europe, attrapées au vol dans une arrière-boutique de Venise."],
        impact:"Savoir écouter est aussi un art : les correspondances et les cercles savants diffusent les idées aussi sûrement que les presses."},
      {t:"Lire à voix haute ta propre traduction d'un passage grec.",juge:"bon",cond:F=>F.metier==="erudit",lock:"réservé au jeune humaniste",sceau:"Ami des humanistes",eff:{renommee:1,erudition:1},reg:"Ta traduction saluée à la table d'Alde.",cible:"presse",
        suite:["Tu tires de ta poche une traduction que tu polis depuis des semaines et tu la lis d'une voix qui tremble à peine. Le silence qui suit est celui qu'on réserve aux bonnes pages. Alde te demande une copie : te voilà des leurs."],
        impact:"Traduire les anciens, c'est l'ouvrage même des humanistes : rendre au présent la voix exacte du passé, mot à mot, sans trahir."},
      {t:"Railler ces pédants et vanter l'expérience directe du monde.",juge:"risque",eff:{virtu:1,renommee:-1},reg:"Les humanistes raillés en pleine table.",cible:"presse",
        suite:["Tu lances que leurs grimoires sentent la poussière et que la vraie connaissance s'attrape sur les quais et les chantiers. Un silence glacial, puis Alde éclate de rire : l'insolence a du vrai, mais la table ne te le pardonne qu'à moitié."],
        impact:"L'observation et l'expérience feront aussi la science de la Renaissance, mais mépriser les livres devant ceux qui les sauvent de l'oubli, c'était mal choisir sa tribune."}
    ]},
  presse:{folio:"Acte II · la commande interdite",src:"folie",
    texte:["Un soir, un client encapuchonné dépose un manuscrit sur le comptoir : une satire mordante contre les abus du clergé, dans le goût de l'Éloge de la folie. L'auteur veut cent exemplaires, vite et sans nom d'imprimeur. Le texte est brillant, drôle, dangereux. Autour de la presse, les compagnons se taisent : ce genre d'encre peut brûler les doigts."],
    consigne:"Le manuscrit attend sur le comptoir. Qu'en fais-tu ?",
    renvois:[
      {t:"L'imprimer sous une fausse adresse, de nuit.",juge:"risque",sceau:"Presse clandestine",eff:{florins:2,eglise:-2},reg:"Cent exemplaires imprimés sous le manteau.",cible:"depart2",
        suite:["Trois nuits de presse à volets clos, une fausse adresse de Bâle en page de titre, et cent exemplaires partent sous des ballots de laine. L'or du client est bon, mais chaque pas de sbire sous la fenêtre te fait maintenant lever la tête."],
        impact:"L'imprimerie diffuse la critique plus vite que jamais, et les autorités l'ont compris : les fausses adresses fleurissent sur les livres qui dérangent."},
      {t:"L'imprimer à ton nom, au grand jour, par principe.",juge:"risque",cible:"depart2",epreuve:{stats:["virtu"],seuil:9,
        ok:{sceau:"Liberté d'examen",eff:{renommee:2,virtu:1,eglise:-1},reg:"La satire imprimée à visage découvert.",txt:"Ton audace fait le tour du quartier.",impact:"Défendre le droit d'examiner et de critiquer, c'est l'esprit critique fait métier : les esprits libres de la ville retiennent ton nom, et l'Église aussi.",suite:["Ton nom en page de titre fait l'effet d'un coup de canon. Les libraires s'arrachent la satire, les esprits libres te saluent, et un chanoine, dit-on, a demandé qui tu étais. La liberté a désormais ton visage."]},
        penalite:{eff:{eglise:-2},reg:"Une impression audacieuse qui tourne mal.",txt:"Le tirage est saisi chez le relieur.",impact:"Le courage sans la prudence livre le livre à ses censeurs : le tirage saisi, il ne reste que les soupçons, et ils portent ton nom."}}},
      {t:"Refuser la commande et rendre le manuscrit.",juge:"bon",eff:{eglise:1},reg:"La commande interdite refusée.",cible:"depart2",
        suite:["Tu rends le manuscrit sans l'ouvrir davantage. Le client disparaît dans la nuit vénitienne. La presse dort tranquille, ta conscience aussi, mais une petite voix te demande longtemps ce que valait ce texte qu'on ne lira pas."],
        impact:"Refuser était le choix le plus sûr. Mais chaque texte refusé par les presses est une idée qui circule moins : la censure commence parfois par la prudence des imprimeurs."}
    ]},
  depart2:{folio:"Acte II · les nouvelles d'Allemagne",
    texte:["L'automne 1517 jette une nouvelle sur les quais : en Allemagne, un moine nommé Martin Luther aurait affiché quatre-vingt-quinze thèses contre le commerce des indulgences, et les presses les recopient plus vite que les chevaux ne courent. Un marchand de Nuremberg, qui a aimé ton travail, t'offre de joindre son convoi vers le nord."],
    consigne:"Le convoi part à l'aube. Pourquoi montes-tu ?",
    renvois:[
      {t:"Pour voir de tes yeux ce qui met l'Allemagne en feu.",juge:"bon",eff:{virtu:1},reg:"En route vers le nord, par curiosité d'esprit.",cible:"tetzel",
        suite:["Tu veux juger sur pièces, comme les humanistes te l'ont appris : ni sur la rumeur, ni sur les sermons, mais de tes propres yeux. Le convoi s'ébranle dans le froid, et chaque étape bruisse davantage du nom de Luther."],
        impact:"Aller voir soi-même avant de juger : l'esprit critique n'est pas qu'une affaire de livres, c'est une manière de voyager."},
      {t:"Pour les affaires : le nord regorge de commandes et de presses.",juge:"bon",eff:{florins:1},reg:"En route vers le nord, pour les affaires.",cible:"tetzel",
        suite:["Les villes d'Empire sont riches, leurs bourgeois aiment les livres et les retables, et les troubles font toujours travailler les presses. Tu pars le coeur léger et la bourse pleine d'espérances."],
        impact:"Les routes du commerce sont aussi celles des idées : marchandises et thèses voyagent dans les mêmes ballots."}
    ]},
  tetzel:{folio:"Acte III · la route des indulgences",src:"indulg",
    texte:["Sur la grand-place d'une ville d'Empire, un prédicateur dominicain a dressé son tréteau, coffre de fer et croix rouge en avant. Il vend des lettres d'indulgence : la remise de la peine due pour les péchés, contre espèces sonnantes, au profit du chantier de Saint-Pierre. La foule se presse, entre ferveur et murmures. C'est exactement ce commerce que les thèses de Wittenberg dénoncent."],
    consigne:"Le prédicateur harangue la foule. Que fais-tu ?",
    renvois:[
      {t:"Acheter une indulgence pour le repos des tiens.",juge:"risque",sceau:"Indulgence achetée",eff:{florins:-2,eglise:1},reg:"Une lettre d'indulgence dans la sacoche.",cible:"theses",
        suite:["Tu poses tes pièces sur le coffre et l'on te tend une lettre au sceau pendant. Pour beaucoup de gens simples, c'est une consolation sincère ; pour les critiques, une marchandise scandaleuse. La lettre pèse étrangement lourd dans ta sacoche."],
        impact:"L'indulgence rassure les fidèles et remplit les coffres de Rome : c'est ce mélange de foi et d'argent qui va faire éclater la Réforme."},
      {t:"Questionner publiquement le prédicateur sur son commerce.",juge:"risque",cible:"theses",epreuve:{stats:["eloquence"],seuil:9,
        ok:{sceau:"Voix critique",eff:{renommee:1,eglise:-1},reg:"Le prédicateur d'indulgences questionné en pleine place.",txt:"La foule murmure en ta faveur.",impact:"Demander où va l'argent et ce que dit l'Évangile, c'est faire de la place publique une salle d'examen : l'esprit critique sort des universités.",suite:["Ta question claque sur la place : si le pardon est de Dieu, pourquoi passe-t-il par un coffre ? Le prédicateur tonne, mais la foule a entendu, et plus d'un bourgeois te cherche du regard avec un sourire entendu."]},
        penalite:{eff:{eglise:-1},reg:"Une question publique tournée en ridicule.",txt:"Le prédicateur te cloue le bec devant la foule.",impact:"Le dominicain a l'habitude des contradicteurs : mal armée, ta question s'est retournée contre toi, et son sbire a noté ton visage."}}},
      {t:"Passer ton chemin sans te mêler de la querelle.",juge:"bon",eff:{},reg:"La querelle des indulgences évitée.",cible:"theses",
        suite:["Tu contournes la place et poursuis ta route. La querelle enfle derrière toi comme un orage d'été : tu n'y as pas trempé, mais tu sens bien qu'elle finira par rattraper tout le monde, toi compris."],
        impact:"La prudence est une vertu de voyageur, mais dans les grandes querelles du siècle, le silence aussi finit par compter."}
    ]},
  theses:{folio:"Acte III · Wittenberg",src:"theses95",
    texte:["Wittenberg, enfin. La petite ville universitaire bourdonne comme une ruche : les thèses de Luther, placardées à la porte de l'église du château, courent l'Empire en réimpressions. Sans l'imprimerie, cette querelle de théologiens serait restée entre quatre murs ; avec elle, c'est toute la chrétienté qui lit, discute et prend parti. Les imprimeurs de la ville croulent sous l'ouvrage."],
    consigne:"Wittenberg t'ouvre ses presses. Quel parti prends-tu ?",
    renvois:[
      {t:"Imprimer et diffuser les thèses, comme tant d'ateliers.",juge:"risque",sceau:"Diffuseur des thèses",eff:{florins:2,renommee:1,eglise:-2},reg:"Les thèses imprimées et diffusées.",cible:"dispute",
        suite:["Tes tirages partent vers les foires par ballots entiers. L'argent rentre, ton nom circule chez les partisans de la Réforme, et quelque part dans un registre romain, il s'inscrit aussi sur une autre liste."],
        impact:"En quelques semaines, l'imprimerie a fait d'une dispute universitaire une affaire européenne : jamais une idée n'avait voyagé si vite."},
      {t:"Copier les arguments des deux camps pour les étudier.",juge:"bon",eff:{erudition:1},reg:"Les arguments des deux camps étudiés à froid.",cible:"dispute",
        suite:["Tu montes un dossier : thèses d'un côté, réponses de Rome de l'autre, et tes notes entre les deux. Comprendre avant de choisir : la méthode est lente, mais elle est à toi."],
        impact:"Peser les arguments des deux camps avant de juger : c'est l'esprit critique appliqué à la plus brûlante querelle du siècle."},
      {t:"Écrire une défense de Rome contre les thèses.",juge:"risque",cible:"dispute",epreuve:{stats:["erudition"],seuil:9,
        ok:{sceau:"Défenseur de Rome",eff:{eglise:2,renommee:1},reg:"Une défense de Rome remarquée.",txt:"Ton opuscule circule jusque chez les chanoines.",impact:"Le camp catholique aussi se bat à coups de presses : la querelle de la Réforme est d'abord une guerre d'imprimés.",suite:["Ton opuscule, serré et bien tourné, plaît aux défenseurs de l'ancienne foi. Des chanoines te font compliment, et ton nom s'inscrit cette fois du bon côté des registres romains."]},
        penalite:{eff:{renommee:-1},reg:"Une défense de Rome trop faible pour convaincre.",txt:"Ton texte se fait démonter en place publique.",impact:"Face aux plumes aiguisées de Wittenberg, une argumentation moyenne se fait tailler en pièces : dans cette guerre d'encre, la médiocrité ne protège personne."}}}
    ]},
  dispute:{folio:"Affrontement · la disputatio",src:"chaire",
    texte:["L'université organise une disputatio solennelle, à la manière de la grande dispute de Leipzig : deux chaires face à face, un auditoire de docteurs et d'étudiants, et une question qui embrase l'Empire, celle de savoir qui peut lire et interpréter les Écritures. Le docteur Konrad, théologien réputé de Leipzig, cherche un contradicteur. Les regards se tournent vers l'étranger d'Italie qui a étudié chez Alde."],
    consigne:"La chaire t'attend. Montes-tu disputer ?",
    renvois:[
      {t:"Monter en chaire et disputer contre le docteur Konrad.",juge:"bon",combat:true},
      {t:"Décliner et laisser la dispute aux théologiens.",juge:"risque",eff:{renommee:-1},reg:"La disputatio déclinée.",cible:"censure",
        suite:["Tu restes dans l'auditoire. Le contradicteur qu'on trouve à ta place se fait broyer en une heure, et tu passes la dispute à composer mentalement les réponses que tu n'as pas osé donner en chaire."],
        impact:"La disputatio est l'arène des idées : on peut la fuir, mais les questions, elles, ne se déclinent pas."}
    ],
    combat:{stat:"eloquence",advNom:"Le docteur Konrad, théologien de Leipzig",advApt:9,advPts:8,advLbl:"La certitude du docteur",jPts:8,jLbl:"Ta conviction",
      aides:[{sceau:"Grammaire grecque",d:1},{sceau:"Ami des humanistes",d:1}],entraves:[],
      win:{sceau:"Vainqueur de la dispute",eff:{renommee:2,erudition:1},reg:"Le docteur Konrad ébranlé en pleine disputatio.",impact:"Tenir tête à un docteur devant l'université, argument contre argument, texte contre texte : voilà la raison à l'oeuvre, telle que les humanistes la rêvent.",cible:"censure",
        suite:["Ronde après ronde, tu retournes ses citations, tu produis les tiennes, et la belle certitude du docteur se fissure devant l'auditoire. Au terme de la dispute, les étudiants frappent des pieds en ton honneur. Konrad te salue d'un signe sec : les vaincus de disputatio ont bonne mémoire."]},
      lose:{eff:{renommee:-1,eglise:-1},reg:"Broyé en disputatio par le docteur Konrad.",impact:"Konrad dispute depuis trente ans : il t'a mené où il voulait. Une défaite en chaire s'oublie, mais les propos qu'on t'y a fait tenir, eux, restent dans les mémoires.",cible:"censure",
        suite:["Le docteur t'a laissé avancer pour mieux te coincer entre deux citations, et l'auditoire a ri. Tu descends de chaire les oreilles brûlantes, avec dans la bouche le goût des arguments trouvés trop tard."]}}},
  censure:{folio:"Affrontement · la saisie",src:"edit",
    texte:["1521. L'Empire a mis Luther au ban et ses écrits à l'index des flammes : l'édit ordonne de rechercher, saisir et brûler les livres interdits. Or l'atelier qui t'emploie a encore un plein grenier d'imprimés compromettants, et les sergents du ban remontent la rue, maison par maison. Le maître imprimeur te supplie : il faut sortir les caisses par les toits et les cours avant qu'ils n'arrivent."],
    consigne:"Les sergents approchent. Que fais-tu des caisses ?",
    renvois:[
      {t:"Sauver le tirage par les cours et les toits, au nez des sergents.",juge:"risque",combat:true},
      {t:"Laisser saisir les caisses et te tenir loin de l'atelier.",juge:"bon",eff:{eglise:1,renommee:-1},reg:"Le tirage abandonné aux sergents.",cible:"entracte",
        suite:["Tu regardes de loin les sergents empiler les caisses et dresser leur bûcher de papier. Le maître imprimeur est ruiné pour une saison. Toi, tu es en règle, et tu n'es pas certain d'en être fier."],
        impact:"Se tenir loin des flammes est le choix le plus sûr. Mais chaque autodafé rappelle ce que les autorités redoutent le plus : des idées qui circulent sans permission."}
    ],
    combat:{stat:"virtu",advNom:"Les sergents du ban impérial",advApt:8,advPts:6,advLbl:"L'avance des sergents",jPts:6,jLbl:"Les caisses à sauver",
      aides:[{sceau:"Casse de caractères",d:1},{sceau:"Compagnon d'imprimerie",d:1}],entraves:[],
      win:{sceau:"Tirage sauvé",eff:{florins:2,renommee:1},reg:"Le tirage sauvé sous le nez des sergents.",impact:"Des caisses de livres passées par les toits pendant que les sergents enfoncent la porte : la censure vient de perdre une manche contre l'imprimerie, et ce ne sera pas la dernière.",cible:"entracte",
        suite:["Cour après cour, toit après toit, les caisses passent de mains en mains jusqu'à la barque qui attend au canal. Quand les sergents défoncent le grenier, ils n'y trouvent que la poussière. Le maître imprimeur t'embrasse comme du bon pain."]},
      lose:{eff:{eglise:-1,florins:-1},reg:"Le tirage saisi, et ton nom noté par les sergents.",impact:"Les sergents ont l'habitude des greniers et des doubles fonds : la cargaison brûle en place publique, et le greffier du ban a inscrit ton nom parmi les suspects.",cible:"entracte",
        suite:["Une caisse échappée des mains, un sergent alerté, et tout s'écroule : le tirage brûle le soir même en place publique. Dans la lueur du bûcher de papier, un greffier note les noms, et le tien y passe."]}}},
  entracte:{folio:"Acte IV · vingt années",src:"chronique",
    texte:["Les années passent comme les pages d'un livre qu'on feuillette trop vite. Les rois de France et l'empereur se déchirent l'Italie ; en 1527, Rome elle-même est mise à sac par les soldats impériaux. La Réforme gagne des princes et des royaumes entiers, l'Europe se fend en deux. Toi, tu vieillis, tu maîtrises ton art, ton nom s'établit. Vingt ans durant, il a bien fallu vivre quelque part."],
    consigne:"Ces vingt années, où les as-tu passées ?",
    renvois:[
      {t:"À Florence, au coeur des ateliers, à perfectionner ton art.",juge:"bon",eff:{adresse:1,renommee:1},reg:"Vingt années d'atelier à Florence.",cible:"rome",
        suite:["Tu retournes aux sources de ton art, dans la ville de la perspective et des concours. Deux décennies d'ouvrage patient font de toi une main que l'on cite, et les commandes ne manquent plus."],
        impact:"Florence reste le grand foyer des arts : c'est là que se forgent les réputations qui traversent les siècles."},
      {t:"Sur les routes d'Empire, de chantier en foire, à faire fortune.",juge:"bon",eff:{florins:2},reg:"Vingt années de chantiers et de foires.",cible:"rome",
        suite:["Retables pour les bourgeois, frontispices pour les imprimeurs, plans pour les conseils de ville : tu vends ton savoir-faire d'une foire à l'autre, et ta bourse s'arrondit d'année en année."],
        impact:"L'Europe des villes et des foires récompense les talents mobiles : la Renaissance est aussi une affaire de routes commerciales."},
      {t:"Au service d'un prince lettré, à enrichir sa bibliothèque.",juge:"bon",eff:{erudition:1,eglise:1},reg:"Vingt années au service d'un prince lettré.",cible:"rome",
        suite:["Un prince collectionneur t'attache à sa cour : manuscrits à expertiser, éditions à surveiller, galerie à orner. Tu vieillis parmi les livres rares, respecté des clercs et bien en cour."],
        impact:"Les cours princières deviennent des foyers de savoir : le mécénat des puissants nourrit les arts autant que les lettres."}
    ]},
  rome:{folio:"Acte IV · Rome",src:"chantier",
    texte:["Rome, 1543. Le chantier de Saint-Pierre dévore la ville, et ta réputation t'y a précédé : un cardinal veut t'attacher aux travaux de sa maison. Mais la Rome qui t'accueille n'est plus celle des humanistes triomphants : depuis l'an dernier, le tribunal de l'Inquisition, rétabli pour juger les hérétiques, fait régner un climat de soupçon. On surveille les propos, les livres, les fréquentations."],
    consigne:"Rome t'ouvre ses portes et te surveille. Où t'installes-tu ?",
    renvois:[
      {t:"Accepter la commande du cardinal et sa protection.",juge:"bon",sceau:"Commande du cardinal",eff:{florins:2,eglise:1},reg:"Au service d'un cardinal romain.",cible:"cosmos",
        suite:["Le cardinal te reçoit entre deux audiences, examine tes ouvrages et te fait porter une avance le soir même. Servir un prince de l'Église, dans la Rome de l'Inquisition, c'est aussi se placer sous un parapluie de pourpre."],
        impact:"À Rome, la protection d'un cardinal vaut autant que le talent : dans un climat de soupçon, les appuis pèsent lourd."},
      {t:"Fréquenter les cercles d'érudits, malgré les soupçons qui les entourent.",juge:"risque",eff:{erudition:1,eglise:-1},reg:"Assidu des cercles savants de Rome.",cible:"cosmos",
        suite:["Dans les jardins et les bibliothèques, les érudits de Rome discutent encore librement, mais à voix plus basse qu'avant. On t'y accueille en confrère. Des oreilles indiscrètes, forcément, notent qui entre et qui sort."],
        impact:"Les cercles savants demeurent le poumon de la pensée, mais l'Inquisition les tient à l'oeil : le savoir se paie désormais en prudence."},
      {t:"Vendre ton savoir-faire au plus offrant, sans t'attacher.",juge:"risque",eff:{florins:3,renommee:-1},reg:"Indépendant dans Rome, au service du plus offrant.",cible:"cosmos",
        suite:["Un palais par-ci, une chapelle par-là : tu factures cher et tu ne dois rien à personne. Les grandes maisons trouvent ce détachement un peu insolent, mais elles paient, et c'est bien l'essentiel."],
        impact:"L'indépendance se monnaie bien dans une ville en chantier, mais elle prive aussi des protections qui, à Rome, valent parfois plus que l'or."}
    ]},
  cosmos:{folio:"Acte IV · le livre du ciel",src:"cosmos",
    texte:["Un libraire de confiance te met entre les mains un volume tout frais sorti des presses de Nuremberg : De revolutionibus, de Nicolas Copernic. L'astronome y propose l'héliocentrisme, un modèle où le Soleil occupe le centre et où la Terre tourne autour de lui, à rebours du géocentrisme enseigné depuis l'Antiquité. Le livre n'est pas interdit, mais l'idée trouble : si la Terre bouge, que reste-t-il des certitudes ?"],
    consigne:"Le livre de Copernic est sur ta table. Qu'en fais-tu ?",
    renvois:[
      {t:"L'étudier de près, calculs et figures à l'appui.",juge:"bon",sceau:"Lecteur de Copernic",eff:{erudition:1},reg:"Le système de Copernic étudié de près.",cible:"manuscrit",
        suite:["Des semaines durant, tu refais les figures, tu compares les modèles, tu mesures ce que chacun explique. L'hypothèse de Copernic est déroutante, mais elle tient debout : la raison, décidément, mène parfois loin du bon sens."],
        impact:"Copernic incarne la Renaissance scientifique : fonder la science sur l'observation et le raisonnement plutôt que sur la seule tradition."},
      {t:"Le refermer : le bon sens montre bien que la Terre ne bouge pas.",juge:"bon",eff:{eglise:1},reg:"Le livre de Copernic refermé au nom du bon sens.",cible:"manuscrit",
        suite:["Tu refermes le volume : les tours ne penchent pas, les pierres tombent droit, la Terre est immobile, voilà tout. C'est l'avis du plus grand nombre, savants compris. L'histoire, elle, prendra son temps pour trancher."],
        impact:"En 1543, rejeter l'héliocentrisme n'a rien d'absurde : les preuves décisives manquent encore, et le débat entre savants ne fait que commencer."},
      {t:"En débattre ouvertement dans les cercles romains.",juge:"risque",cible:"manuscrit",epreuve:{stats:["eloquence"],seuil:8,
        ok:{eff:{renommee:1,erudition:1},reg:"Le débat sur Copernic animé avec brio.",txt:"Les érudits en redemandent.",impact:"Faire dialoguer les modèles du ciel devant un auditoire, arguments et figures à l'appui : le débat d'idées est le laboratoire de la science nouvelle.",suite:["Tes soirées coperniciennes font courir la petite société savante de Rome : on y confronte les modèles, on y refait les calculs, on s'y dispute joyeusement. L'idée circule, et ton nom avec elle."]},
        penalite:{eff:{renommee:-1},reg:"Un débat sur Copernic tourné en confusion.",txt:"Tu t'emmêles dans les épicycles.",impact:"Défendre une hypothèse qu'on ne maîtrise pas à fond, c'est la désservir : les auditeurs sont repartis moins convaincus qu'avant."}}}
    ]},
  manuscrit:{folio:"Acte IV · le manuscrit suspect",src:"donation",
    texte:["Le prélat qui administre les archives te fait mander en grand secret. Sur son pupitre, un parchemin vénérable : la donation par laquelle l'empereur Constantin aurait légué l'Occident aux papes, il y a plus de mille ans. Des voix, depuis Lorenzo Valla, osent la dire fausse. Le prélat veut un avis discret et sûr : ce document, pilier de bien des droits, est-il authentique ?"],
    consigne:"Le parchemin est devant toi. Comment mènes-tu l'expertise ?",
    renvois:[
      {t:"Éprouver le texte mot à mot, à la manière des philologues.",juge:"bon",cible:"verdict",epreuve:{stats:["erudition"],seuil:9,
        ok:{sceau:"Philologue",eff:{erudition:1},reg:"Le manuscrit passé au crible de la philologie.",txt:"Les anachronismes sautent aux yeux, l'un après l'autre.",impact:"Comparer chaque mot à son époque, traquer les termes nés trop tard : c'est la méthode de Valla, l'esprit critique changé en science exacte.",suite:["Ligne après ligne, le parchemin avoue : des titres qui n'existaient pas au 4e siècle, des tournures de chancellerie bien plus tardives, un latin qui sent son Moyen Âge. Le doute n'est plus permis : ce texte est un faux, écrit des siècles après Constantin."]},
        penalite:{eff:{},reg:"Une expertise restée sans conclusion.",txt:"Le latin résiste à ton examen.",impact:"La philologie est un art exigeant : sans une érudition à toute épreuve, le parchemin garde son secret, et il faudra te prononcer autrement."}}},
      {t:"T'en remettre à l'avis des docteurs du prélat.",juge:"risque",eff:{eglise:1},reg:"L'expertise laissée aux docteurs du prélat.",cible:"verdict_flou",
        suite:["Les docteurs du prélat concluent doctement à l'authenticité, comme on l'attendait d'eux. Tu contresignes leur avis sans avoir vraiment examiné toi-même. La question, pourtant, continue de te trotter dans la tête."],
        impact:"S'en remettre aux autorités sans examiner soi-même : c'est exactement ce que l'esprit critique de la Renaissance apprend à ne plus faire."},
      {t:"Refuser l'expertise : ce parchemin sent la poudre.",juge:"risque",eff:{virtu:-1},reg:"L'expertise du manuscrit refusée.",cible:"verdict_flou",
        suite:["Tu déclines avec toutes les politesses requises : trop vieux, trop délicat, pas ta spécialité. Le prélat n'insiste pas, mais son regard te pèse longtemps. On ne refuse pas grand-chose, à Rome, sans que cela se sache."],
        impact:"Éviter les questions dangereuses protège, un temps. Mais la vérité qu'on refuse d'examiner reste au service de ceux qui s'en servent."}
    ]},
  verdict:{folio:"Acte IV · le verdict",src:"philologie",
    texte:["Tu sais. La donation est un faux, forgé des siècles après Constantin, et ta démonstration tient sur trois feuillets serrés que n'importe quel érudit honnête devra admettre. Mais ce faux soutient des droits bien réels, et la Rome de l'Inquisition n'aime pas qu'on touche à ses piliers. Trois feuillets, et tout ton avenir posé dessus."],
    consigne:"Ta démonstration est prête. Qu'en fais-tu ?",
    renvois:[
      {t:"La publier, quoi qu'il en coûte : la vérité ne se met pas au coffre.",juge:"risque",sceau:"Vérité publiée",eff:{virtu:1,renommee:2,eglise:-3},reg:"La démonstration du faux publiée.",cible:"tribunal",
        suite:["Les trois feuillets, imprimés sous le manteau, courent Rome en une semaine, puis l'Italie. Les érudits saluent la démonstration, les chancelleries s'étranglent. Une convocation au parfum de cire et d'encens ne tarde pas : le Saint-Office veut t'entendre."],
        impact:"Publier une vérité qui dérange, en sachant le prix : c'est l'esprit critique poussé jusqu'au courage, et c'est lui que le tribunal voudra faire taire."},
      {t:"Remettre la preuve au prélat, sous le sceau du secret.",juge:"bon",sceau:"Preuve enterrée",eff:{florins:2,eglise:1},reg:"La preuve du faux remise en secret.",cible:"concile",
        suite:["Le prélat lit tes feuillets en silence, blêmit, puis les range dans un coffre dont tu n'entendras plus jamais parler. Il sait, tu sais, et le coffre garde tout. Ta discrétion est récompensée avec une générosité qui ressemble à un prix du silence."],
        impact:"La vérité remise aux autorités qui ont intérêt à la taire : elle existe, mais elle ne circule pas. Le savoir sans la diffusion change peu de choses au monde."},
      {t:"Monnayer ton silence auprès des intéressés.",juge:"risque",sceau:"Silence acheté",eff:{florins:3,renommee:-1},reg:"Le silence sur le faux monnayé.",cible:"concile",
        suite:["Un intermédiaire discret fixe le prix, et il est bon. Les feuillets brûlent dans ta cheminée pendant qu'on te compte l'or. Il ne reste de ta démonstration qu'une chaleur de braise et un petit goût de cendre qui ne part pas."],
        impact:"Vendre son silence rapporte plus que la vérité, et coûte autre chose : ce que les humanistes appellent la dignité de l'homme n'a pas de prix de rachat."}
    ]},
  verdict_flou:{folio:"Acte IV · le doute",
    texte:["L'affaire du parchemin se referme sans toi, mais elle laisse une trace : à Rome, on sait désormais que tu as approché le document, et chacun interprète ta réserve à sa façon. Prudence pour les uns, tiédeur pour les autres. Dans la ville du soupçon, même le silence a des lecteurs."],
    consigne:"L'affaire classée, comment retrouves-tu ta place ?",
    renvois:[
      {t:"Redoubler de zèle dans les commandes d'Église.",juge:"bon",eff:{eglise:1,florins:1},reg:"Le zèle retrouvé dans les commandes d'Église.",cible:"concile",
        suite:["Chapelles, missels, portraits de prélats : tu enchaînes les commandes pieuses avec un soin irréprochable. Les langues se calment. À Rome, rien ne blanchit mieux qu'un travail bien payé au service des bonnes causes."],
        impact:"Dans la Rome de la Contre-Réforme, l'art devient aussi un gage de fidélité : servir l'Église, c'est se mettre à l'abri."},
      {t:"Reprendre tes travaux savants, sans bruit mais sans te cacher.",juge:"risque",eff:{erudition:1},reg:"Les travaux savants repris discrètement.",cible:"concile",
        suite:["Tu retournes à tes chères études, porte entrouverte : ni bravade, ni cachette. Les érudits t'en savent gré, les soupçonneux en prennent note. Tu as choisi de rester toi-même, à voix modérée."],
        impact:"Continuer à penser dans un climat de surveillance, sans provocation ni reniement : c'est le chemin de crête qu'ont suivi bien des esprits du siècle."}
    ]},
  tribunal:{folio:"Affrontement · le Saint-Office",src:"saintoffice",
    texte:["La salle est haute et froide, le crucifix immense. Devant toi, l'inquisiteur feuillette un dossier où ta vie entière tient en dénonciations : lectures, fréquentations, imprimés, propos. Le tribunal de l'Inquisition, rétabli en 1542 pour juger les hérétiques, ne condamne pas toujours, mais il n'oublie jamais. Il te faudra défendre chaque année de ta vie, pied à pied, avec pour seules armes ta parole et ta mémoire."],
    consigne:"L'inquisiteur ouvre l'interrogatoire. Il n'y a plus qu'une voie : répondre.",
    renvois:[
      {t:"Faire face au tribunal et défendre ta vie, réponse après réponse.",juge:"bon",combat:true}
    ],
    combat:{stat:"eloquence",advNom:"L'inquisiteur du Saint-Office",advApt:9,advPts:8,advLbl:"La certitude du tribunal",jPts:8,jLbl:"Ta conviction",
      aides:[{sceau:"Commande du cardinal",d:1},{sceau:"Protégé d'un mécène",d:1},{sceau:"Défenseur de Rome",d:1},{sceau:"Philologue",d:1}],
      entraves:[{sceau:"Presse clandestine",d:1},{sceau:"Diffuseur des thèses",d:1},{sceau:"Anatomiste de l'ombre",d:1}],
      win:{sceau:"Blanchi par le tribunal",eff:{eglise:2,renommee:1},reg:"Blanchi par le tribunal du Saint-Office.",impact:"Sortir libre du Saint-Office, en 1546, c'est un exploit de parole et de sang-froid : le tribunal relâche sa prise, mais son dossier, lui, ne brûle jamais.",cible:"concile",
        suite:["Réponse après réponse, tu démontes les dénonciations, tu produis tes appuis, tu retournes les citations. La certitude du tribunal s'effrite jusqu'à ce que l'inquisiteur, d'un geste las, referme le dossier : rien d'assez ferme pour condamner. Tu ressors dans le soleil de Rome, libre, et changé pour toujours."]},
      lose:{eff:{eglise:-1},reg:"Convaincu d'erreur par le tribunal.",impact:"L'inquisiteur interroge depuis des décennies : chaque réponse t'a enfoncé un peu plus. Le tribunal te déclare convaincu d'erreur, et te laisse le dernier choix qui reste.",cible:"sentence",
        suite:["Pièce après pièce, l'inquisiteur resserre son filet : une lecture avouée, un témoin cité, une date qui accuse. Ta défense s'épuise. Le tribunal te déclare convaincu d'erreur et suspect d'hérésie. Reste la question qui décide de tout."]}}},
  sentence:{folio:"Acte IV · la sentence",
    texte:["Le greffier lit la sentence d'une voix égale : convaincu d'erreur, l'accusé sera reçu en pénitence s'il abjure publiquement ; s'il persiste, il sera remis au bras séculier. Tout le monde, dans la salle, sait ce que signifient ces mots. On te tend la formule d'abjuration. La plume est là, l'encre est fraîche."],
    consigne:"La formule d'abjuration est devant toi. Signes-tu ?",
    renvois:[
      {t:"Abjurer publiquement et sauver ta vie.",juge:"bon",sceau:"Abjuration",eff:{eglise:3,renommee:-2},reg:"L'abjuration prononcée devant le tribunal.",cible:"concile",
        suite:["Tu lis la formule à genoux, cierge en main, devant l'assistance convoquée. Les mots te brûlent la bouche et te sauvent la vie. Galilée, un siècle plus tard, fera le même choix. On vit, après. Autrement, mais on vit."],
        impact:"Abjurer sous la contrainte n'efface pas ce qu'on a pensé : cela mesure seulement ce que le pouvoir du moment exige des esprits libres."},
      {t:"Persister, et signer de ton propre nom ce que tu crois vrai.",juge:"risque",sceau:"Persistant",eff:{virtu:2},reg:"Le refus d'abjurer, signé en pleine audience.",cible:"nF_bucher",
        suite:["Tu repousses la formule et tu signes, d'une main qui ne tremble presque pas, une déclaration où tu maintiens tout. Le silence de la salle est immense. Le bras séculier t'attend à la porte."],
        impact:"Persister devant l'Inquisition, c'est choisir ses idées contre sa vie. D'autres l'ont fait, comme Giordano Bruno en 1600 : l'histoire retient leurs noms, et le prix qu'ils ont payé."}
    ]},
  concile:{folio:"Acte IV · le concile",src:"trente",
    texte:["1545. Dans les Alpes, à Trente, l'Église réunit son grand concile pour répondre à la Réforme : doctrine réaffirmée, clergé repris en main, Contre-Réforme lancée. L'Europe entière retient son souffle, et chacun doit trouver sa place dans ce monde qui se referme. Toi, au soir d'une vie de choix, trois routes s'ouvrent une dernière fois."],
    consigne:"Le siècle tourne la page. Quelle est ta dernière route ?",
    renvois:[
      {t:"Mettre ton art et ton nom au service de la Contre-Réforme.",juge:"bon",sceau:"Serviteur de la Contre-Réforme",eff:{eglise:2,florins:2},reg:"Au service de la Contre-Réforme.",cibleFn:F=>evaluerFin(F),
        suite:["Églises à décorer, livres à orner, images à mettre au service de la foi réaffirmée : la Contre-Réforme a besoin de mains sûres, et la tienne en est une. Tu finis tes jours occupé, honoré et bien en cour."],
        impact:"La Contre-Réforme mobilise les arts pour reconquérir les fidèles : bien des carrières du siècle s'achèvent à son service."},
      {t:"Passer en France, où la cour accueille les talents d'Italie.",juge:"bon",sceau:"Passage en France",eff:{renommee:1},cibleFn:F=>evaluerFin(F),reg:"Le chemin de la France choisi.",
        suite:["Comme Léonard de Vinci l'avait fait avant toi, invité par François 1er au Clos Lucé, tu prends la route des Alpes vers une cour qui collectionne les talents d'Italie. La Renaissance, décidément, voyage bien."],
        impact:"En attirant les artistes italiens, les rois de France diffusent la Renaissance au nord des Alpes : les idées et les arts suivent les routes des cours."},
      {t:"Poursuivre librement tes travaux, en te tenant à ta place.",juge:"bon",eff:{erudition:1},cibleFn:F=>evaluerFin(F),reg:"La liberté discrète choisie jusqu'au bout.",
        suite:["Ni service, ni exil : tu choisis ta table, tes livres, tes ouvrages, et la prudence comme compagne. C'est une liberté à voix basse, comme le siècle en laisse encore, et tu comptes bien l'user jusqu'à la dernière page."],
        impact:"Entre soumission et martyre, bien des esprits de la Renaissance ont choisi cette voie médiane : penser librement, publier prudemment."}
    ]},
  nF_maitre:{fin:true,titre:"La main que les siècles retiendront",
    prose:["Les commandes affluent jusqu'à ta mort, et après elle. Les jeunes copient tes ouvrages comme tu copiais ceux des maîtres, et un biographe à la manière de Vasari consigne ta vie parmi celles des plus excellents artistes. La perspective, le réalisme, l'harmonie des proportions : tout ce que la Renaissance a inventé, ta main l'aura porté un peu plus loin. Sur ton tombeau, un seul mot latin, celui qui a guidé ta vie : Virtù."]},
  nF_humaniste:{fin:true,titre:"Un nom dans la république des lettres",
    prose:["Tes travaux circulent de Bâle à Venise, tes lettres tissent leur fil dans la grande correspondance des savants, et l'on cite ton nom à côté de ceux qui ont remis l'être humain, sa raison et son éducation au centre de tout. Tu n'as pas seulement traversé la Renaissance : tu as aidé à la penser. Les presses réimprimeront tes pages longtemps après que la dernière chandelle de ton cabinet se sera éteinte."]},
  nF_presse:{fin:true,titre:"L'encre qui a conquis l'Europe",
    prose:["Ton enseigne d'imprimeur devient l'une des plus sûres d'Europe : éditions soignées, formats habiles, réseaux de foire en foire. Des milliers de volumes portant ta marque dorment aujourd'hui dans les bibliothèques du continent. Gutenberg a inventé le procédé ; des gens comme toi en ont fait une révolution. Chaque lecteur qui ouvre un de tes livres, quelque part, prolonge ta vie d'une page."]},
  nF_france:{fin:true,titre:"L'hôte de la cour de France",
    prose:["La cour de France te fait l'accueil qu'elle réservait aux talents d'Italie depuis Léonard de Vinci : logis, pension et liberté d'ouvrage. Dans les chantiers de la Loire et de Fontainebleau, ton savoir-faire italien se mêle au goût français, et la Renaissance franchit les Alpes un peu grâce à toi. Tu finis tes jours honoré dans un royaume qui collectionne les oeuvres comme d'autres les provinces."]},
  nF_concile:{fin:true,titre:"Le pinceau de la Contre-Réforme",
    prose:["Tu meurs comblé d'honneurs et de commandes, au service d'une Église qui a repris la main. Tes ouvrages ornent les églises restaurées par le concile, et ton nom figure aux registres des serviteurs fidèles. Les esprits libres de ta jeunesse auraient peut-être froncé les sourcils, mais tu as choisi ton camp dans un siècle qui n'en laissait guère le choix, et ce camp t'a bien rendu tes services."]},
  nF_abjure:{fin:true,titre:"Une vie sauvée, une voix éteinte",
    prose:["Tu vis vieux, prudent et surveillé. L'abjuration t'a rendu la liberté en te prenant la parole : plus une ligne risquée, plus un débat, plus une expertise. Les registres du Saint-Office gardent ton dossier ouvert jusqu'à ta mort. Certains soirs, tu relis en secret les pages de ta jeunesse, et tu te demandes ce qu'aurait pesé ta voix si le siècle avait été moins dur aux esprits libres."]},
  nF_ombre:{fin:true,titre:"Une vie dans l'ombre des ateliers",
    prose:["Ni gloire ni disgrâce : une vie d'ouvrage honnête, de commandes moyennes et de soirs tranquilles. Tu auras vu passer le siècle le plus étonnant de mémoire d'homme, l'imprimerie, la perspective, la Réforme, le concile, sans jamais monter sur son théâtre. Les archives ne retiendront pas ton nom, mais quelques ouvrages de ta main, anonymes, traverseront les siècles : c'est une immortalité discrète, et ce n'est pas la pire."]},
  nF_bucher:{fin:true,titre:"Le bûcher",
    prose:["Le bras séculier a fait son office en place publique, comme la sentence l'ordonnait. Tu as refusé d'abjurer ce que ta raison tenait pour vrai, et le siècle te l'a fait payer au prix du feu. Mais les paroles qu'un bûcher veut réduire en cendres ont une étrange manière de se répandre avec la fumée : des copies de tes feuillets circulent déjà sous le manteau, et l'histoire, qui a de la mémoire, inscrira ton nom parmi ceux qui n'ont pas plié."]},
  nF_prison:{fin:true,titre:"Les geôles du Saint-Office",
    prose:["La dénonciation est arrivée avant que tu aies pu te défendre, et les geôles du Saint-Office se sont refermées sur toi. Les procès de l'Inquisition savent durer des années : le tien s'éteint doucement, comme toi, entre quatre murs épais. Dehors, la Renaissance continue sans toi ses découvertes et ses querelles. Ta faute, aux yeux du tribunal, aura été de trop t'approcher des flammes du siècle sans jamais t'assurer d'un abri."]},
  nF_misere:{fin:true,titre:"La misère",
    prose:["La bourse vide, les dettes au cou, plus de crédit chez les marchands ni de commandes chez les grands : la misère t'a rattrapé comme elle rattrapait tant de gens de talent au siècle des mécènes. Tu finis parmi les besogneux des chantiers, à louer ta main à la journée. La Renaissance est un âge d'or, mais l'or y va à qui sait le retenir : le talent sans les florins reste une chandelle sans mèche."]},
  nF_fortune:{fin:true,titre:"La roue de la Fortune",
    prose:["Trois fois les dés t'ont trahi, et la rumeur a fait le reste : on ne confie ni commande ni cargaison à qui la Fortune tourne le dos. Les penseurs de ton siècle aimaient représenter la Fortune en roue qui élève et précipite les mortels ; la tienne a choisi la descente. Machiavel écrivait que la virtù peut dompter la Fortune à demi : l'autre moitié, tu viens d'apprendre ce qu'elle coûte."]},
  nF_oubli:{fin:true,titre:"L'oubli",
    prose:["Tu vieillis sans que personne se souvienne de ton nom. Pas d'ennemis, pas d'amis puissants, pas d'ouvrage qui porte ta marque : le siècle des concours et des dédicaces n'a pas su où t'inscrire. La Renaissance a inventé la gloire moderne, celle qui se gagne et s'imprime ; elle a inventé du même geste son revers, l'oubli de ceux qui n'ont pas osé signer. Ton histoire s'éteint comme une page qu'on tourne sans l'avoir lue."]}
};
function evaluerFin(F){
  const s=F.sceaux,ren=F.renommee,flo=F.florins,egl=F.eglise,adr=F.adresse,eru=F.erudition;
  if(s.has("Persistant")) return "nF_bucher";
  if(s.has("Abjuration")) return egl<=4?"nF_prison":"nF_abjure";
  if(ren<=2) return "nF_oubli";
  if(s.has("Passage en France")&&ren>=6) return "nF_france";
  if(s.has("Serviteur de la Contre-Réforme")&&egl>=10) return "nF_concile";
  if(eru>=12&&(s.has("Philologue")||s.has("Vérité publiée")||s.has("Ami des humanistes"))) return "nF_humaniste";
  if(adr>=12&&s.has("Lauréat du concours")&&ren>=7) return "nF_maitre";
  if(flo>=10&&(s.has("Compagnon d'imprimerie")||s.has("Presse clandestine")||s.has("Tirage sauvé"))) return "nF_presse";
  if(ren>=9&&adr>=10) return "nF_maitre";
  if(ren>=9) return "nF_humaniste";
  return "nF_ombre";
}
